import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"大過","description":"周易正義 - 大過","frontmatter":{"title":"大過","description":"周易正義 - 大過"},"headers":[],"relativePath":"classics/zhengyi/028.md","filePath":"classics/zhengyi/028.md"}'),l={name:"classics/zhengyi/028.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>澤風大過</p></blockquote><blockquote><p>卦辭：棟橈，利有攸往，亨。</p></blockquote><blockquote><p>彖曰：大過，大者過也。棟撓，本末弱也。剛過而中，巽而說，行。利有攸往，乃亨。大過之時大矣哉！</p></blockquote><h1 id="大過" tabindex="-1">大過 <a class="header-anchor" href="#大過" aria-label="Permalink to “大過”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“大過”。○正義曰：“過”謂過越之“過”，非經過之“過”。此衰難之世，唯陽爻，乃大能過越常理以拯患難也。故曰“大過”。以人事言之，猶若聖人過越常理以拯患難也。○注“音相過之過”。○正義曰：“相過”者，謂相過越之甚也，非謂相過從之“過”，故《象》雲“澤滅木”。是過越之甚也。四陽在中，二陰在外，以陽之過越之甚也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“棟撓”者，謂屋棟也。本之與末俱撓弱，以言衰亂之世，始終皆弱也。“利有攸往亨”者，既遭衰難，聖人“利有攸往”，以拯患難，乃得亨通，故云“利有攸往亨”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="大過-大者過也。-​" tabindex="-1">大過，大者過也。 ​ <a class="header-anchor" href="#大過-大者過也。-​" aria-label="Permalink to “大過，大者過也。 ​”">​</a></h3><p>王弼：大者乃能過也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋大過之義也。“大者過”，謂盛大者乃能過其分理以拯難也。故於二爻陽處陰位，乃能拯難也，亦是過甚之義。</p><h3 id="棟撓-本末弱也。-​" tabindex="-1">“棟撓”，本末弱也。 ​ <a class="header-anchor" href="#棟撓-本末弱也。-​" aria-label="Permalink to ““棟撓”，本末弱也。 ​”">​</a></h3><p>王弼：初為本，而上為末也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“棟撓”義。以大過本末俱弱，故屋棟撓弱也，似若衰難之時始終弱。</p><h3 id="剛過而中-​" tabindex="-1">剛過而中， ​ <a class="header-anchor" href="#剛過而中-​" aria-label="Permalink to “剛過而中， ​”">​</a></h3><p>王弼：謂二也。居陰，“過”也；處二，“中”也。拯弱興衰，不失其中也。</p><h3 id="巽而說行-​" tabindex="-1">巽而說行， ​ <a class="header-anchor" href="#巽而說行-​" aria-label="Permalink to “巽而說行， ​”">​</a></h3><p>王弼：“巽而說行”，以此救難，難乃濟也。</p><h3 id="利有攸往-乃亨。-​" tabindex="-1">“利有攸往”，乃亨。 ​ <a class="header-anchor" href="#利有攸往-乃亨。-​" aria-label="Permalink to ““利有攸往”，乃亨。 ​”">​</a></h3><p>王弼：危而弗持，則將安用？故往乃亨。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“剛過而中巽而說行利有攸往乃亨”者，此釋“利有攸往乃亨”義。“剛過而中”謂二也。以陽處陰，是剛之過極之甚，則陽來拯此陰難，是過極之甚也。“巽而說行”者，既以巽順和說而行，難乃得濟，故“利有攸往得亨”也。故云“乃亨”。</p><h3 id="大過之時大矣哉-​" tabindex="-1">大過之時大矣哉！ ​ <a class="header-anchor" href="#大過之時大矣哉-​" aria-label="Permalink to “大過之時大矣哉！ ​”">​</a></h3><p>王弼：是君子有為之時也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：此廣說大過之美。言當此大過之時，唯君子有為拯難，其功甚大，故曰“大矣哉”也。</p><h2 id="象曰-澤滅木-大過。君子以獨立不懼-遁世無悶。-​" tabindex="-1">象曰：澤滅木，大過。君子以獨立不懼，遁世無悶。 ​ <a class="header-anchor" href="#象曰-澤滅木-大過。君子以獨立不懼-遁世無悶。-​" aria-label="Permalink to “象曰：澤滅木，大過。君子以獨立不懼，遁世無悶。 ​”">​</a></h2><p>王弼：此所以為“大過”，非凡所及也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“澤滅木”者，澤體處下，木體處上，澤無滅木之理。今雲“澤滅木”者，乃是澤之甚極而至滅木，是極大過越之義。其大過之卦有二義也：一者物之自然大相過越常分，即此“澤滅木”是也。二者大人大過越常分以拯患難，則九二“枯楊生稊，老夫得其女妻”是也。“君子以獨立不懼，遁世無悶”者，明君子於衰難之時，卓爾獨立，不有畏懼，隱遁於世而無憂悶，欲有遁難之心，其操不改。凡人遇此則不能，然唯君子獨能如此，是其過越之義。</p><h2 id="初六-藉用白茅-無咎。-​" tabindex="-1">初六：藉用白茅，無咎。 ​ <a class="header-anchor" href="#初六-藉用白茅-無咎。-​" aria-label="Permalink to “初六：藉用白茅，無咎。 ​”">​</a></h2><p>王弼：以柔處下，過而可以“無咎”，其唯慎乎！</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：以柔處下，心能謹慎，薦藉於物，用絜白之茅，言以絜素之道奉事於上也。“無咎”者，既能謹慎如此，雖遇大過之難，而“無咎”也。以柔道在下，所以免害。故《象》雲“柔在下也”。</p><h3 id="《象》曰-藉用白茅-柔在下也。-​" tabindex="-1">《象》曰：“藉用白茅”，柔在下也。 ​ <a class="header-anchor" href="#《象》曰-藉用白茅-柔在下也。-​" aria-label="Permalink to “《象》曰：“藉用白茅”，柔在下也。 ​”">​</a></h3><h2 id="九二-枯楊生稊-老夫得其女妻-無不利。-​" tabindex="-1">九二：枯楊生稊，老夫得其女妻，無不利。 ​ <a class="header-anchor" href="#九二-枯楊生稊-老夫得其女妻-無不利。-​" aria-label="Permalink to “九二：枯楊生稊，老夫得其女妻，無不利。 ​”">​</a></h2><p>王弼：“稊”者，楊之秀也。以陽處陰，能過其本而救其弱者也。上無其應，心無持吝處過以此，無衰不濟也。故能令枯楊更生稊，老夫更得少妻，拯弱興衰，莫盛斯爻，故“無不利”也。老過則枯，少過則稚。以老分少，則稚者長；以稚分老，則枯者榮，過以相與之謂也。大過至衰而已至壯，以至壯輔至衰，應斯義也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰藉用白茅”至“無不利”。○正義曰：“枯楊生稊”者，“枯”謂枯稿，“稊”謂“楊之秀”者。九二以陽處陰，能過其本分，而救其衰弱。上無其應，心無特吝，處大過之時，能行此道，無有衰者不被拯濟。故衰者更盛，猶若枯槁之楊，更生少壯之稊；枯老之夫，得其少女為妻也。“無不利”者，謂拯弱興衰，莫盛於此。以斯而行，無有不利也。○注“稊者楊之秀也”至“應斯義也”。○正義曰：“稊”者楊柳之穗，故云“楊之秀也”。“以陽處陰，能過其本而救其弱”者，若以陽處陽，是依其本分。今以陽處陰，是過越本分，拯救陰弱也。“老過則枯，少過則稚”者，老之太過則枯槁，少之太過則幼稚也。“以老分少則稚者長也”，謂老夫減老而與女妻，女妻得之而更益長，故云“以老分少則稚者長也”。“以稚分老則枯者榮”者，謂女妻減少而與老夫，老夫得之，似若槁者而更得生稊，故云“則枯者榮也。”雲“大過至衰而已至壯，以至壯輔至衰，應斯義”者，此大過之卦，本明至壯輔至衰，不論至衰減至壯。故輔嗣此《注》特雲“以至壯輔至衰也”。“《象》曰過以相與”者，因至壯而輔至衰，似女妻而助老夫，遂因雲老夫減老而與少，猶若至衰減衰而與壯也。其實不然也。</p><h3 id="《象》曰-老夫女妻-過以相與也。-​" tabindex="-1">《象》曰：“老夫女妻”，過以相與也。 ​ <a class="header-anchor" href="#《象》曰-老夫女妻-過以相與也。-​" aria-label="Permalink to “《象》曰：“老夫女妻”，過以相與也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“老夫女妻”之義。若老夫而有老妻，是依分相對。今老夫而得女妻，是過分相與也。老夫得女妻，是女妻以少而與老夫。老夫得少而更壯，是女妻過分而與夫也。女妻而得少夫，是依分相對。今女妻得老夫，是老夫減老而與少。女妻既得其老則益長，是老夫過分而與妻也，故云“過以相與”。《象》直雲“老夫”、“女妻”，不雲“枯楊生稊”者，“枯楊”則是老夫也，“生稊”則女妻也。其意相似，故《象》略而不言。</p><h2 id="九三-棟橈-兇。-​" tabindex="-1">九三：棟橈，兇。 ​ <a class="header-anchor" href="#九三-棟橈-兇。-​" aria-label="Permalink to “九三：棟橈，兇。 ​”">​</a></h2><p>王弼：居大過之時，處下體之極，不能救危拯弱，以隆其棟，而以陽處陽，自守所居，又應於上，繫心在一，宜其淹弱而兇衰也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：居大過之時，處下體之極，以陽居陽，不能救危拯弱，唯自守而已。獨應於上，繫心在一，所以“兇”也。心既褊狹，不可以輔救衰難，故《象》雲“不可以有輔也”。</p><h3 id="《象》曰-棟橈-之兇-不可以有輔也。-​" tabindex="-1">《象》曰：“棟橈”之兇，不可以有輔也。 ​ <a class="header-anchor" href="#《象》曰-棟橈-之兇-不可以有輔也。-​" aria-label="Permalink to “《象》曰：“棟橈”之兇，不可以有輔也。 ​”">​</a></h3><h2 id="九四-棟隆-吉。有它吝。-​" tabindex="-1">九四：棟隆，吉。有它吝。 ​ <a class="header-anchor" href="#九四-棟隆-吉。有它吝。-​" aria-label="Permalink to “九四：棟隆，吉。有它吝。 ​”">​</a></h2><p>王弼：體屬上體，以陽處陰，能拯其弱，不為下所橈者也，故“棟隆”吉也。而應在初，用心不弘，故“有它吝”也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“棟隆吉”者，體居上體，以陽處陰，能拯救其弱，不為下所橈，故得棟隆起而獲吉也。“有它吝”者，以有應在初，心不弘闊，故“有它吝”也。</p><h3 id="《象》曰-棟隆-之吉-不橈乎下也。-​" tabindex="-1">《象》曰：“棟隆”之吉，不橈乎下也。 ​ <a class="header-anchor" href="#《象》曰-棟隆-之吉-不橈乎下也。-​" aria-label="Permalink to “《象》曰：“棟隆”之吉，不橈乎下也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“棟隆之吉”，以其能拯於難，不被橈乎在下，故得“棟隆吉”。九四應初，行又謙順，能拯於難，然唯只拯初，初謂下也。下得其拯，猶若所居屋棟隆起，下必不橈。若何得之，不被橈乎在下。但《經》文雲“棟橈”，《彖》釋“棟橈”者，本末弱也。以屋棟橈弱而偏，則屋下榱柱亦先弱。柱為本，棟為末，觀此《彖》辭，是足見其義。故子產雲：“棟折榱崩，僑將壓焉。”以屋棟橈折，則榱柱亦同崩，此則義也。</p><h2 id="九五-枯楊生華-老婦得其士夫-無咎無譽。-​" tabindex="-1">九五：枯楊生華，老婦得其士夫，無咎無譽。 ​ <a class="header-anchor" href="#九五-枯楊生華-老婦得其士夫-無咎無譽。-​" aria-label="Permalink to “九五：枯楊生華，老婦得其士夫，無咎無譽。 ​”">​</a></h2><p>王弼：處得尊位，而以陽處陽，未能拯危。處得尊位，亦未有橈，故能生華，不能生稊；能得夫，不能得妻。處“棟橈”之世，而為“無咎無譽”，何可長哉！故生華不可久，士夫誠可醜也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>“九五枯楊生華”至“無咎無譽”。正義曰：“枯楊生華”者，處得尊位而以陽居陽，未能拯危，不如九二“枯楊生稊”。但以處在尊位，唯得“枯楊生華”而巳。言其衰老，雖被拯救，其益少也。又似年老之婦，得其彊壯士夫，婦已衰老，夫又彊大，亦是其益少也。所拯難處少，才得無咎而已，何有聲譽之美？故“無咎無譽”也。○注“處得尊位”至“誠可醜也”。○正義曰：“處得尊位，亦未有橈”者，以九三不得尊位，故有棟橈。今九五雖與九三同以陽居陽，但九五處得尊位，功雖未廣，亦未有橈弱。若其橈弱，不能拯難，不能使“枯楊生華”也。以在尊位，微有拯難，但其功狹少，但使“枯楊生華”而已，“不能生稊”也。“能得夫，不能得妻”者，若拯難功闊，則“老夫得其女妻”，是得少之甚也。今既拯難功狹，但能使老婦得士夫而已，不能使女妻，言老婦所得利益薄少，皆為拯難功薄，故所益少也。</p><h3 id="《象》曰-枯楊生華-何可久也-老婦士夫-亦可醜也。-​" tabindex="-1">《象》曰：“枯楊生華”，何可久也？老婦士夫，亦可醜也。 ​ <a class="header-anchor" href="#《象》曰-枯楊生華-何可久也-老婦士夫-亦可醜也。-​" aria-label="Permalink to “《象》曰：“枯楊生華”，何可久也？老婦士夫，亦可醜也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“枯楊生華，何可久”者，枯稿之楊，被拯才得生華，何可長久？尋當衰落也。“老婦士夫，亦可醜也”者，婦當少稚於夫，今年老之婦，而得彊壯士夫，亦可醜辱也。此言九五不能廣拯衰難，但使“枯楊生華”而已，但使“老婦得其士夫”而已。拯難狹劣，故不得長久，誠可醜辱，言不如九二也。</p><h2 id="上六-過涉滅頂-兇-無咎。-​" tabindex="-1">上六：過涉滅頂，兇，無咎。 ​ <a class="header-anchor" href="#上六-過涉滅頂-兇-無咎。-​" aria-label="Permalink to “上六：過涉滅頂，兇，無咎。 ​”">​</a></h2><p>王弼：處太過之極，過之甚也。涉難過甚，故至於“滅頂兇”。志在救時，故不可咎也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：處大過之極，是過越之甚也。以此涉危難，乃至於滅頂，言涉難深也。既滅其頂，所以“兇”也。“無咎”者，所以涉難滅頂，至於兇亡，本欲濟時拯難，意善功惡，無可咎責。此猶龍逄、比干，憂時危亂，不懼誅殺，直言深諫，以忤無道之主，遂至滅亡。其意則善，而功不成，復有何咎責？此亦“過涉滅頂兇無咎”之象，故《象》雲“不可咎”，言不可害於義理也。</p><h3 id="《象》曰-過涉-之兇-不可咎也。-​" tabindex="-1">《象》曰：“過涉”之兇，不可咎也。 ​ <a class="header-anchor" href="#《象》曰-過涉-之兇-不可咎也。-​" aria-label="Permalink to “《象》曰：“過涉”之兇，不可咎也。 ​”">​</a></h3><p>王弼：雖兇無咎，不害義也。</p>',70)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
